var n=`0545-omani-halwa`;var a=`world-0545`;var t=`OM`;var r=`western-asia`;var o=8;var s=102;var m={en:`Omani Halwa`,ua:`Оманська халва`};var g={en:`A traditional dish from Oman, centered on cornstarch, pistachio. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Оман. Основні складники: кукурудзяний крохмаль, фісташка. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Dissolve sugar in water over medium heat to make a clear syrup; do not burn or darken it into caramel.`,ua:`Розчиніть цукор у воді на середньому вогні до прозорого сиропу; не перегрівайте до темної карамелі.`,t:[`caramelizing-sugar`],m:12,i:[[`white-granulated-sugar`,270,`g`],[`water`,280,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`cornstarch`,105,`g`],[`rose-water`,25,`ml`],[`ground-cardamom`,5,`g`],[`saffron-threads`,.25,`g`],[`unsalted-butter`,55,`g`]]},{en:`Cook the starch-sugar mixture over very low heat for approximately 75 minutes, stirring constantly until thick, glossy and translucent; do not refrigerate as if it contained gelatin.`,ua:`Уварюйте крохмально-цукрову масу на дуже малому вогні приблизно 75 хвилин, безперервно помішуючи до густоти, блиску й напівпрозорості; не охолоджуйте як желатиновий десерт.`,t:[`slow-simmer-reduction`],m:75,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pistachio`,70,`g`]]}];var d={slug:n,id:a,country:`OM`,region:r,servings:8,minutes:102,title:m,text:g,steps:l};export{t as country,d as default,a as id,s as minutes,r as region,o as servings,n as slug,l as steps,g as text,m as title};